#!/usr/bin/env node
// Translate the practice chapter prose that nobody else translates, and cache it in
// `assets/practice.zh.json`.
//
// Why this exists: practice content ships inside the app (`assets/practice.json`, generated by
// `scripts/gen_practice.dart` from the live lichess API), and chapter names, descriptions and the
// commentary inside its PGNs are authored English prose. Upstream localizes the *section* and
// *study* level only — see
// `translation/source/practice.xml`, whose 67 keys cover sections, study names and study
// descriptions — because lila itself has no translation source below that. The chapter text is
// therefore English on lichess.org too, in every language, and the app has no l10n path for it
// (`PracticeChapter.name` is rendered straight from the JSON, see `practice_chapter_screen.dart`).
//
// The output is keyed by the English source string rather than by chapter id, which makes the
// overlay content-addressed: if upstream rewords a chapter the lookup simply misses and the app
// falls back to English, ids changing is a non-event, and strings repeated across chapters are
// stored once. A human can hand-edit the JSON; the script only ever adds or refreshes entries.
//
// Usage:
//   LLM_BASE_URL=... LLM_API_KEY=... LLM_MODEL=... \
//     node scripts/gen-practice-zh.mjs [options]
//
// Options:
//   --dry-run     translate and report, write nothing
//   --limit <n>   stop after n batches (cheap smoke test)
//   --force       retranslate every string, ignoring the cache
//
// Env (same names as the Go proxy and translate-zh.mjs, so one gateway serves both):
//   LLM_BASE_URL, LLM_API_KEY, LLM_MODEL, LLM_BATCH_LIMIT, LLM_BATCH_CHARS, LLM_TIMEOUT_SECONDS,
//   LLM_REASONING_EFFORT
//
// Sourcing the proxy's own env file is the easy way to reach the key, but its
// LLM_TIMEOUT_SECONDS is a page-load budget — a request that slow has already lost the user —
// while this is an offline run with nobody waiting. Override it on the command line for that:
//   LLM_TIMEOUT_SECONDS=120 node scripts/gen-practice-zh.mjs

import { readFileSync, writeFileSync, existsSync } from 'fs'
import { fileURLToPath } from 'url'
import { dirname, join } from 'path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const ROOT = join(__dirname, '..')
const PRACTICE = join(ROOT, 'assets', 'practice.json')
const OUTPUT = join(ROOT, 'assets', 'practice.zh.json')

const cfg = {
  baseUrl: (process.env.LLM_BASE_URL ?? '').replace(/\/+$/, ''),
  apiKey: process.env.LLM_API_KEY ?? '',
  model: process.env.LLM_MODEL ?? '',
  batchLimit: Number(process.env.LLM_BATCH_LIMIT ?? 30),
  batchChars: Number(process.env.LLM_BATCH_CHARS ?? 4000),
  timeoutMs: Number(process.env.LLM_TIMEOUT_SECONDS ?? 180) * 1000,
  // Sent as `reasoning_effort` on every request; `off` omits the field entirely.
  // A model that deliberates over a translation spends the run doing it: against
  // the gateway this was written for, a 40-string batch took 26s and 5.9k
  // completion tokens (5.7k of them reasoning) with thinking left on, and 3.1s
  // and 790 tokens with it off — for the same translations. 624 strings is 16
  // batches, so that difference is a minute against half an hour.
  reasoningEffort: (process.env.LLM_REASONING_EFFORT ?? 'none').trim(),
}
if (cfg.reasoningEffort === 'off') cfg.reasoningEffort = ''

const opt = { dryRun: false, limit: Infinity, force: false }
const argv = process.argv.slice(2)
for (let i = 0; i < argv.length; i++) {
  const a = argv[i]
  if (a === '--dry-run') opt.dryRun = true
  else if (a === '--force') opt.force = true
  else if (a === '--limit') opt.limit = Number(argv[++i])
  else if (a === '--help' || a === '-h') {
    console.log(readFileSync(fileURLToPath(import.meta.url), 'utf8').split('\n').slice(2, 31).join('\n'))
    process.exit(0)
  } else {
    console.error(`Unknown option: ${a}`)
    process.exit(1)
  }
}

if (!cfg.baseUrl || !cfg.model || (!cfg.apiKey && !/localhost|127\.0\.0\.1/.test(cfg.baseUrl))) {
  console.error('LLM_BASE_URL and LLM_MODEL must be set (LLM_API_KEY for hosted providers)')
  process.exit(1)
}

// ---- collect the English strings the app can display -------------------------

/** The `{...}` comments of a chapter's PGN, which is where its reading text lives. */
function pgnComments(pgn) {
  const out = []
  let from = 0
  while (true) {
    const open = pgn.indexOf('{', from)
    if (open < 0) break
    const close = pgn.indexOf('}', open + 1)
    if (close < 0) break
    const text = pgn.slice(open + 1, close).trim()
    // A comment holding shape directives is a drawing, not prose: `%cal`/`%csl` put
    // arrows and squares on the board, and there is nothing in them to translate.
    if (text !== '' && !/%c[als]/.test(text)) out.push(text)
    from = close + 1
  }
  return out
}

/** Every string that reaches the screen from a practice chapter, deduplicated. */
function collectStrings() {
  const practice = JSON.parse(readFileSync(PRACTICE, 'utf8'))
  const strings = new Set()
  const add = (s) => {
    if (typeof s === 'string' && s.trim() !== '') strings.add(s)
  }
  for (const section of practice.sections ?? []) {
    for (const study of section.studies ?? []) {
      for (const chapter of study.chapters ?? []) {
        add(chapter.name)
        add(chapter.description)
        for (const hint of chapter.hints ?? []) add(hint)
        for (const deviation of chapter.deviations ?? []) add(deviation)
        // The authored commentary the player reads between moves. The app overlays
        // this by rewriting the comment text inside the PGN — see `_localizedPgn` in
        // `lib/src/model/practice/practice_structure.dart`, which matches on exactly
        // the string collected here.
        if (typeof chapter.pgn === 'string') for (const comment of pgnComments(chapter.pgn)) add(comment)
      }
    }
  }
  return [...strings]
}

function loadCache() {
  if (opt.force || !existsSync(OUTPUT)) return {}
  const parsed = JSON.parse(readFileSync(OUTPUT, 'utf8'))
  const cache = {}
  for (const [english, chinese] of Object.entries(parsed)) {
    if (typeof chinese === 'string' && chinese.trim() !== '') cache[english] = chinese
  }
  return cache
}

// ---- batches ----------------------------------------------------------------

/** Short strings first, so a `--limit` smoke test covers the visible titles before the prose. */
function makeBatches(strings) {
  const sorted = [...strings].sort((a, b) => a.length - b.length)
  const batches = []
  let batch = []
  let chars = 0
  for (const s of sorted) {
    if (batch.length >= cfg.batchLimit || chars + s.length > cfg.batchChars) {
      if (batch.length > 0) batches.push(batch)
      batch = []
      chars = 0
    }
    batch.push(s)
    chars += s.length
  }
  if (batch.length > 0) batches.push(batch)
  return batches
}

const SYSTEM_PROMPT = `You are a professional software localizer translating the Lichess chess app's practice content from English into Simplified Chinese.

Input: a JSON array of strings. Each is either the name of a practice chapter (a short title), the description of one, a hint shown during a gamebook chapter, the comment shown when the player plays a wrong move, or a paragraph of the author's commentary that the player reads on the board between moves.

Requirements:
- Use standard Mainland Chinese chess terminology: 王 king / 后 queen / 车 rook / 象 bishop / 马 knight / 兵 pawn; 将军 check, 将杀 checkmate, 和棋 draw, 升变 promotion, 战术 tactics, 局面 position, 开局 opening, 残局 endgame, 对局 game, 棋步 move.
- Keep brand names in Latin script: Lichess, Stockfish.
- Preserve the escape sequence \\n (literally backslash-n) exactly where the input has it, and keep paragraph breaks where the input has them.
- Square names (e1, h8), piece letters (K, Q, R), move notation (Nf3, O-O) and digit counts ("Mate in 4") must survive unchanged; translate the sentence around them.
- Chapter names are titles: translate them as short noun phrases, not sentences. Do not add a full stop to a title that has none.
- Descriptions and move commentary are instructional prose addressed to the player: keep the second person, keep the imperative mood.
- Do not add punctuation or trailing full stops that the source lacks.`

// The task itself has to be restated in the user turn, not only in the system message.
//
// The gateway this runs against answers a request whose user turn is a bare JSON array with
// "What would you like me to do with this text?" — it reads the array as material to be
// worked on and never treats it as an instruction to translate, however explicit the system
// message is. Measured against it on 2026-10-11: system message alone -> a chat reply; the
// same system message with these two lines in front of the array -> the translations. The
// system message is still worth sending (it is what keeps "Vančura"/"Lichess" in Latin
// script rather than transliterated), it just cannot carry the request on its own.
const USER_INSTRUCTION = `Translate each string in this JSON array into Simplified Chinese.
Return ONLY a JSON array of the SAME LENGTH, in the SAME ORDER, containing the translations.

`

async function translateBatchOnce(batch) {
  const res = await fetch(`${cfg.baseUrl}/chat/completions`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      ...(cfg.apiKey ? { authorization: `Bearer ${cfg.apiKey}` } : {}),
    },
    // No max_tokens: a reasoning model emits its thinking before any content, and a cap
    // sized for the translation would cut it off mid-thought and return nothing.
    // reasoning_effort is what stops that from happening in the first place (see cfg).
    body: JSON.stringify({
      model: cfg.model,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: USER_INSTRUCTION + JSON.stringify(batch, null, 1) },
      ],
      temperature: 0.2,
      ...(cfg.reasoningEffort ? { reasoning_effort: cfg.reasoningEffort } : {}),
    }),
    signal: AbortSignal.timeout(cfg.timeoutMs),
  })
  if (!res.ok) {
    const body = (await res.text()).slice(0, 300)
    const err = new Error(`LLM HTTP ${res.status}: ${body}`)
    // A rejected key or a malformed model name fails the same way on the next attempt.
    err.retryable = res.status === 429 || res.status >= 500
    throw err
  }
  const json = await res.json()
  const content = json?.choices?.[0]?.message?.content
  if (typeof content !== 'string' || content.trim() === '') {
    throw new Error(
      `LLM response had no message content (finish_reason=${json?.choices?.[0]?.finish_reason})`,
    )
  }
  const text = content.replace(/^```(?:json)?\s*/m, '').replace(/```\s*$/, '')
  const start = text.indexOf('[')
  const end = text.lastIndexOf(']')
  if (start === -1 || end === -1) throw new Error(`LLM did not return a JSON array: ${content.slice(0, 300)}`)
  const parsed = JSON.parse(text.slice(start, end + 1))
  // Position is the only mapping there is, so a wrong length is not repairable: which
  // returned string belongs to which input would be a guess. Ask again instead.
  if (
    !Array.isArray(parsed) ||
    parsed.length !== batch.length ||
    parsed.some((s) => typeof s !== 'string' || s.trim() === '')
  ) {
    throw new Error(
      `LLM returned ${Array.isArray(parsed) ? parsed.length : 'no'} strings for ${batch.length} inputs`,
    )
  }
  return new Map(batch.map((s, i) => [s, parsed[i]]))
}

async function translateBatch(batch) {
  let lastErr
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      return await translateBatchOnce(batch)
    } catch (e) {
      lastErr = e
      if (e.retryable === false || attempt === 3) break
      console.log(`  batch of ${batch.length} failed (${e.message.slice(0, 100)}); retrying`)
    }
  }
  throw lastErr
}

// ---- main -------------------------------------------------------------------

// Only strings that are still on screen are kept, so the file cannot accumulate dead entries.
function writeOutput(strings, cache) {
  const out = {}
  for (const s of strings.sort()) if (cache[s] !== undefined) out[s] = cache[s]
  if (!opt.dryRun) writeFileSync(OUTPUT, JSON.stringify(out, null, 1) + '\n', 'utf8')
  return out
}

async function main() {
  const strings = collectStrings()
  const cache = loadCache()
  const todo = strings.filter((s) => !(s in cache))
  console.log(`${strings.length} strings on screen, ${Object.keys(cache).length} cached, ${todo.length} to translate`)

  const batches = makeBatches(todo)
  let done = 0
  for (const batch of batches) {
    if (done >= opt.limit) {
      console.log(`--limit ${opt.limit} reached, stopping`)
      break
    }
    const started = Date.now()
    const translated = await translateBatch(batch)
    for (const [english, chinese] of translated) cache[english] = chinese
    done += 1
    // Written after every batch rather than once at the end: a run this long over a
    // hosted gateway is one 502 away from losing everything, and a file that is
    // already partly translated makes the rerun resume instead of start over.
    writeOutput(strings, cache)
    console.log(
      `  batch ${done}/${batches.length}: ${batch.length} strings in ${((Date.now() - started) / 1000).toFixed(1)}s` +
        `  e.g. ${JSON.stringify(batch[0].slice(0, 40))} -> ${JSON.stringify(cache[batch[0]].slice(0, 40))}`,
    )
  }

  const out = writeOutput(strings, cache)
  if (opt.dryRun) {
    console.log(`dry run: would write ${Object.keys(out).length} entries to ${OUTPUT}`)
    return
  }
  console.log(`wrote ${Object.keys(out).length} entries to ${OUTPUT}`)
  const untranslated = strings.filter((s) => out[s] === undefined).length
  if (untranslated > 0) console.log(`note: ${untranslated} strings left untranslated (the app falls back to English)`)
}

main().catch((e) => {
  console.error(e.message ?? e)
  process.exit(1)
})
